"""Models for the scoping-only site dictionary generated by canonical-naaccr.

The file is built by ``python -m canonical_naaccr.cipoc_scoping``. These models
cover the envelope and the tissue table; ``tools/scoping.py`` loads and checks it.
"""

from pydantic import BaseModel, ConfigDict, Field


class TissueCodes(BaseModel):
    """One tissue's code tables."""

    codes: dict[int, dict[str, str]] = Field(
        description="Code-to-description tables keyed by NAACCR item ID. Item 400 holds the tissue's Primary Site codes.",
    )


class ScopingDictionary(BaseModel):
    """The scoping-only site dictionary.

    Sections not modeled yet (algorithms, items, histology, blocks, schemas) are
    ignored, so a file from a newer generator still loads.
    """

    model_config = ConfigDict(extra="ignore")

    sources: dict[str, str] = Field(
        description="Source and version of each reference the file is built from, e.g. eod: 'eod_public 3.3'.",
    )
    tissues: dict[str, TissueCodes] = Field(
        description="Code tables for each GrossSite tissue other than 'unspecified'.",
    )
